private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (i < 0 || i >= bb.limit()) {
        throw new IllegalArgumentException("Index out of bounds");
    }
    int first = bb.get(i) & 0xFF;
    int codePoint;
    int bytes;

    if ((first & 0x80) == 0) { // 1-byte sequence 0xxxxxxx
        codePoint = first;
        bytes = 1;
    } else if ((first & 0xE0) == 0xC0) { // 2-byte sequence 110xxxxx 10xxxxxx
        if (i + 1 >= bb.limit())
            throw new BufferUnderflowException();
        int second = bb.get(i + 1) & 0xFF;
        if ((second & 0xC0) != 0x80)
            throw new IllegalArgumentException("Invalid continuation byte at index " + (i + 1));
        codePoint = ((first & 0x1F) << 6) | (second & 0x3F);
        bytes = 2;
    } else if ((first & 0xF0) == 0xE0) { // 3-byte sequence 1110xxxx 10xxxxxx 10xxxxxx
        if (i + 2 >= bb.limit())
            throw new BufferUnderflowException();
        int second = bb.get(i + 1) & 0xFF;
        int third = bb.get(i + 2) & 0xFF;
        if ((second & 0xC0) != 0x80 || (third & 0xC0) != 0x80)
            throw new IllegalArgumentException("Invalid continuation bytes at indices " + (i + 1) + ", " + (i + 2));
        codePoint = ((first & 0x0F) << 12) | ((second & 0x3F) << 6) | (third & 0x3F);
        bytes = 3;
    } else if ((first & 0xF8) == 0xF0) { // 4-byte sequence 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
        if (i + 3 >= bb.limit())
            throw new BufferUnderflowException();
        int second = bb.get(i + 1) & 0xFF;
        int third = bb.get(i + 2) & 0xFF;
        int fourth = bb.get(i + 3) & 0xFF;
        if ((second & 0xC0) != 0x80 || (third & 0xC0) != 0x80 || (fourth & 0xC0) != 0x80)
            throw new IllegalArgumentException("Invalid continuation bytes at indices " + (i + 1) + ", " + (i + 2) + ", " + (i + 3));
        codePoint = ((first & 0x07) << 18) | ((second & 0x3F) << 12) | ((third & 0x3F) << 6) | (fourth & 0x3F);
        bytes = 4;
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 leading byte at index " + i);
    }

    sb.appendCodePoint(codePoint);
    return i + bytes;
}

