private void enlarge(final int size) {
    int required = nbytes + size;
    if (required <= b.length) {
        return;
    }
    int newCapacity = Math.max(b.length * 2, required);
    if (newCapacity < 0) { // overflow guard
        newCapacity = Integer.MAX_VALUE;
    }
    byte[] newb = new byte[newCapacity];
    System.arraycopy(b, 0, newb, 0, nbytes);
    b = newb;
}

