public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pGenericType = (ParameterizedType) genericType;
    Type raw = pGenericType.getRawType();
    if (!(raw instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) raw;

    ParameterizedType matchedPT = null;
    Class<?> curClass = targetType;
    while (curClass != null && matchedPT == null) {
        // check superclass
        Type superT = curClass.getGenericSuperclass();
        if (superT instanceof ParameterizedType) {
            ParameterizedType superPT = (ParameterizedType) superT;
            if (superPT.getRawType() == rawClass) {
                matchedPT = superPT;
                break;
            }
        }
        // check interfaces
        for (Type it : curClass.getGenericInterfaces()) {
            if (it instanceof ParameterizedType) {
                ParameterizedType itPT = (ParameterizedType) it;
                if (itPT.getRawType() == rawClass) {
                    matchedPT = itPT;
                    break;
                }
            }
        }
        curClass = curClass.getSuperclass();
    }
    if (matchedPT == null) {
        return null;
    }
    Type[] actualArgs = matchedPT.getActualTypeArguments();
    Class<?>[] res = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type t = actualArgs[i];
        if (t instanceof Class<?>) {
            res[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            Type rawT = ((ParameterizedType) t).getRawType();
            if (rawT instanceof Class<?>) {
                res[i] = (Class<?>) rawT;
            } else {
                return null;
            }
        } else {
            return null;
        }
    }
    return res;
}

