static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the starting day of the bucket
    int startDay = ((day - 1) / dayStep) * dayStep + 1;

    // Reconstruct the date as a long in YYYYMMDD format
    return year * 10000L + month * 100L + startDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int end = index + len;
    int total = 0;
    int i = index;
    while (i < end) {
        int cp = Character.codePointAt(str, i, end);
        if (cp <= 0x7F) {
            total += 1;
        } else if (cp <= 0x7FF) {
            total += 2;
        } else if (cp <= 0xFFFF) {
            total += 3;
        } else {
            total += 4;
        }
        i += Character.charCount(cp);
    }
    return total;
}

