    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
        }
    }

    int newPos = pos + byteLength;
    if (newPos > buf.length) {
        int newSize = Math.max(newPos, 2 * buf.length);
        byte[] tmp = new byte[newSize];
        System.arraycopy(buf, 0, tmp, 0, pos);
        buf = tmp;
    }

    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, buf, pos, byteLength);
    } else {
        for (int i = pos; i < newPos; i++) {
            buf[i] = 0;
        }
    }

    pos = newPos;
    return this;
}

