public void removeFromTreeEdgeList(){
    // Detach from source node’s tree edge list
    if (prevTreeEdgeSrc != null) {
        prevTreeEdgeSrc.nextTreeEdgeSrc = nextTreeEdgeSrc;
    } else {
        source.setTreeEdgeHead(nextTreeEdgeSrc);
    }
    if (nextTreeEdgeSrc != null) {
        nextTreeEdgeSrc.prevTreeEdgeSrc = prevTreeEdgeSrc;
    } else {
        source.setTreeEdgeTail(prevTreeEdgeSrc);
    }

    // Detach from target node’s tree edge list
    if (prevTreeEdgeTgt != null) {
        prevTreeEdgeTgt.nextTreeEdgeTgt = nextTreeEdgeTgt;
    } else {
        target.setTreeEdgeHead(nextTreeEdgeTgt);
    }
    if (nextTreeEdgeTgt != null) {
        nextTreeEdgeTgt.prevTreeEdgeTgt = prevTreeEdgeTgt;
    } else {
        target.setTreeEdgeTail(prevTreeEdgeTgt);
    }

    // Clear this edge’s own pointers
    prevTreeEdgeSrc = nextTreeEdgeSrc = null;
    prevTreeEdgeTgt = nextTreeEdgeTgt = null;
}

public static String findAndSubst(String key,Properties props){
    String value = props.getProperty(key);
    if(value == null){
        return null;
    }
    StringBuffer sb = new StringBuffer();
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    while(matcher.find()){
        String var = matcher.group(1);
        String replacement = props.getProperty(var);
        if(replacement == null){
            replacement = matcher.group(0);
        }else{
            replacement = replacement.replace("\\", "\\\\").replace("$", "\\$");
        }
        matcher.appendReplacement(sb, replacement);
    }
    matcher.appendTail(sb);
    return sb.toString();
}

