@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Allow null values
    if (value == null) {
        return null;
    }

    // Only convert if requested target type is Character (wrapper) or primitive char
    if (type.equals(Character.class) || type.equals(char.class)) {
        // Already a Character
        if (value instanceof Character) {
            return value;
        }

        // String or CharSequence: return first character (error on empty)
        if (value instanceof CharSequence) {
            CharSequence cs = (CharSequence) value;
            if (cs.length() == 0) {
                throw new IllegalArgumentException(
                    "Cannot convert an empty CharSequence to a Character");
            }
            return cs.charAt(0);
        }

        // Number: convert to int and cast to char
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            return (char) intVal;
        }

        // Enum: use name's first character
        if (value instanceof Enum<?>) {
            String name = ((Enum<?>) value).name();
            if (name.isEmpty()) {
                throw new IllegalArgumentException(
                    "Enum name is empty, cannot convert to Character");
            }
            return name.charAt(0);
        }

        // Fallback: use toString (first character)
        String strVal = value.toString();
        if (strVal.isEmpty()) {
            throw new IllegalArgumentException(
                "Cannot convert an empty string representation to a Character");
        }
        return strVal.charAt(0);
    }

    // If the conversion target is not Character, delegate or fail
    throw new IllegalArgumentException(
        "Conversion to type " + type.getName() + " is not supported for value of type " +
        value.getClass().getName());
}
