public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Start with the next odd number >= desiredCapacity
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    int upperLimit;
    if (desiredCapacity >= 1000) {
        upperLimit = (int) Math.ceil(desiredCapacity * 1.11);
    } else {
        upperLimit = Integer.MAX_VALUE;
    }

    while (candidate <= upperLimit) {
        if (candidate == 2) {
            return 2;
        }
        if (candidate % 2 == 0) {
            candidate += 1;
            continue;
        }
        boolean isPrime = true;
        int sqrt = (int) Math.sqrt(candidate);
        for (int i = 3; i <= sqrt; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2;
    }

    // If no prime was found within the 11% range, continue searching indefinitely
    while (true) {
        if (candidate == 2) {
            return 2;
        }
        if (candidate % 2 == 0) {
            candidate += 1;
            continue;
        }
        boolean isPrime = true;
        int sqrt = (int) Math.sqrt(candidate);
        for (int i = 3; i <= sqrt; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2;
    }
}

