    for(Map.Entry<String,JsonElement> entry: jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement elem = entry.getValue();
        if("ats".equals(key)){
            if(elem!=null && elem.isJsonPrimitive() && elem.getAsJsonPrimitive().isNumber()){
                result.put(key, elem.getAsNumber().longValue());
            } else {
                result.put(key, elem!=null?elem.toString():null);
            }
        } else if(elem!=null && elem.isJsonPrimitive()){
            JsonPrimitive prim = elem.getAsJsonPrimitive();
            if(prim.isString()){
                result.put(key, prim.getAsString());
            } else if(prim.isNumber()){
                result.put(key, prim.getAsNumber());
            } else if(prim.isBoolean()){
                result.put(key, prim.getAsBoolean());
            } else {
                result.put(key, null);
            }
        } else if(elem!=null && elem.isJsonObject()){
            result.put(key, buildContent(elem.getAsJsonObject()));
        } else if(elem!=null && elem.isJsonArray()){
            List<Object> list = new ArrayList<>();
            for(JsonElement e: elem.getAsJsonArray()){
                if(e!=null && e.isJsonPrimitive()){
                    JsonPrimitive p = e.getAsJsonPrimitive();
                    if(p.isString()){
                        list.add(p.getAsString());
                    } else if(p.isNumber()){
                        list.add(p.getAsNumber());
                    } else if(p.isBoolean()){
                        list.add(p.getAsBoolean());
                    } else {
                        list.add(null);
                    }
                } else if(e!=null && e.isJsonObject()){
                    list.add(buildContent(e.getAsJsonObject()));
                } else {
                    list.add(null);
                }
            }
            result.put(key, list);
        } else {
            result.put(key, null);
        }
    }
