public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder out = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            out.append(c);
            continue;
        }
        if (i == len - 1) {
            // trailing backslash, copy it as is
            out.append('\\');
            break;
        }
        char next = str.charAt(++i);
        switch (next) {
            case 'b':
                out.append('\b');
                break;
            case 't':
                out.append('\t');
                break;
            case 'n':
                out.append('\n');
                break;
            case 'f':
                out.append('\f');
                break;
            case 'r':
                out.append('\r');
                break;
            case '\"':
                out.append('\"');
                break;
            case '\'':
                out.append('\'');
                break;
            case '\\':
                out.append('\\');
                break;
            case 'u':
                // Unicode escape: must be 4 hex digits
                if (i + 4 >= len) {
                    throw new Exception("Invalid Unicode escape sequence at position " + (i - 1));
                }
                String hex = str.substring(i + 1, i + 5);
                try {
                    int code = Integer.parseInt(hex, 16);
                    out.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid Unicode escape: \\u" + hex, e);
                }
                i += 4; // skip the 4 hex digits
                break;
            default:
                // If it's a digit, handle as octal escape (0-7)
                if (next >= '0' && next <= '7') {
                    int oct = next - '0';
                    // up to 3 digits
                    int count = 1;
                    while (count < 3 && i + 1 < len) {
                        char nxt = str.charAt(i + 1);
                        if (nxt >= '0' && nxt <= '7') {
                            oct = (oct << 3) + (nxt - '0');
                            i++;
                            count++;
                        } else {
                            break;
                        }
                    }
                    out.append((char) oct);
                } else {
                    // Unrecognized escape, keep the backslash and the char
                    out.append(next);
                }
                break;
        }
    }
    return out.toString();
