    if (set1.size() <= set2.size()) {
        for (V v : set1) {
            if (set2.contains(v)) {
                result.add(v);
            }
        }
    } else {
        for (V v : set2) {
            if (set1.contains(v)) {
                result.add(v);
            }
        }
    }
    return result;
}

