protected int removeUnusedNodes(){
    // Counts the number of inactive Category nodes removed from the tree.
    int removedCount = 0;
    // Assume the tree has a single root node accessible as 'root'.
    if (root == null) {
        return 0;
    }
    // If the root itself is inactive, remove the entire tree.
    if (!root.isActive()) {
        // Count all nodes in the subtree rooted at 'root'.
        java.util.Deque<Category> countStack = new java.util.ArrayDeque<>();
        countStack.push(root);
        while (!countStack.isEmpty()) {
            Category cur = countStack.pop();
            removedCount++;
            java.util.List<Category> list = cur.getChildren();
            if (list != null) {
                for (Category child : list) {
                    countStack.push(child);
                }
            }
        }
        root = null;
        return removedCount;
    }
    // Traverse the tree iteratively, removing inactive descendants.
    java.util.Deque<java.util.Iterator<Category>> stack = new java.util.ArrayDeque<>();
    stack.push(root.getChildren().iterator());
    while (!stack.isEmpty()) {
        java.util.Iterator<Category> it = stack.peek();
        if (!it.hasNext()) {
            stack.pop();
            continue;
        }
        Category child = it.next();
        if (!child.isActive()) {
            // Count and remove the entire subtree rooted at 'child'.
            java.util.Deque<Category> countStack = new java.util.ArrayDeque<>();
            countStack.push(child);
            while (!countStack.isEmpty()) {
                Category cur = countStack.pop();
                removedCount++;
                java.util.List<Category> list = cur.getChildren();
                if (list != null) {
                    for (Category gc : list) {
                        countStack.push(gc);
                    }
                }
            }
            it.remove(); // removes 'child' from its parent's list
        } else {
            // Traverse deeper into the active child.
            stack.push(child.getChildren().iterator());
        }
    }
    return removedCount;
}

