private void check(String modelName) throws IllegalStateException {
    // Retrieve the list of sharding key indices for the given model.
    java.util.List<Integer> indices = ShardingHelper.getShardingKeyIndices(modelName);
    if (indices == null || indices.isEmpty()) {
        // No sharding keys or only one key is trivially continuous.
        return;
    }
    // Sort indices to ensure order.
    java.util.Collections.sort(indices);
    // Verify that indices are consecutive.
    int expected = indices.get(0);
    for (int idx : indices) {
        if (idx != expected) {
            throw new IllegalStateException(
                "Sharding key indices for model '" + modelName + "' are not continuous. " +
                "Expected " + expected + " but found " + idx);
        }
        expected++;
    }
}

