int addConstantNameAndType(final String name,final String descriptor){
    // Build a unique key for the (name, descriptor) pair
    String key = name + "|" + descriptor;

    // If we already have a Constant_NameAndType_info for this pair, return its index
    Integer existingIndex = nameAndTypeIndexMap.get(key);
    if (existingIndex != null) {
        return existingIndex;
    }

    // Ensure the name and descriptor UTF‑8 entries exist in the constant pool
    int nameIndex = addUtf8Constant(name);
    int descriptorIndex = addUtf8Constant(descriptor);

    // Create the new CONSTANT_NameAndType_info entry
    ConstantNameAndTypeInfo nameAndType = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
    constantPool.add(nameAndType);

    // The index of the new entry is the last position in the pool
    int index = constantPool.size() - 1;

    // Cache the index so subsequent requests can be resolved quickly
    nameAndTypeIndexMap.put(key, index);

    return index;
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }

    int start = 0;
    int end = input.length();

    // Detect quoted string (either " or ')
    if (end > 0) {
        char first = input.charAt(0);
        if ((first == '"' || first == '\'')
                && end > 1 && input.charAt(end - 1) == first) {
            start = 1;
            end = end - 1;
        }
    }

    StringBuilder sb = new StringBuilder(end - start);
    int i = start;
    while (i < end) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < end) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'a':
                    sb.append('\u0007'); // alert
                    break;
                case 'v':
                    sb.append('\u000B'); // vertical tab
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                default:
                    // Unknown escape: keep the next character as is
                    sb.append(next);
                    break;
            }
            i += 2; // skip the escape
        } else {
            sb.append(c);
            i++;
        }
    }

    return sb.toString();
}

