public void abbreviate(final int nameStart, final StringBuffer buf) {
    final String n = this.name;
    if (n == null || n.isEmpty()) {
        return;
    }
    int len = n.length();
    int start = Math.max(0, nameStart);
    if (start >= len) {
        return;
    }
    boolean needNext = true;
    for (int i = start; i < len; i++) {
        char ch = n.charAt(i);
        if (needNext) {
            buf.append(ch);
            needNext = false;
        }
        if (!Character.isLetterOrDigit(ch) || ch == '_' || ch == '-' || ch == '.' || ch == ' ') {
            needNext = true;
        } else if (Character.isUpperCase(ch) && i > start && Character.isLowerCase(n.charAt(i - 1))) {
            needNext = true;
        }
    }
}

