public static String applyRelativePath(String path, String relativePath){
    if (path == null || relativePath == null) {
        return null;
    }
    boolean isAbsolute = path.startsWith("/");
    java.util.LinkedList<String> stack = new java.util.LinkedList<>();
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    if (isAbsolute) {
        if (stack.isEmpty()) {
            return "/";
        }
        StringBuilder sb = new StringBuilder("/");
        java.util.Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            sb.append(it.next());
            if (it.hasNext()) {
                sb.append("/");
            }
        }
        return sb.toString();
    } else {
        if (stack.isEmpty()) {
            return ".";
        }
        StringBuilder sb = new StringBuilder();
        java.util.Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            sb.append(it.next());
            if (it.hasNext()) {
                sb.append("/");
            }
        }
        return sb.toString();
    }
}

